1. /**
2.  * PoutineSubmission CRUD, the 5-active-submission cap, and Tag association logic
3.  * for the "Submit a poutine" experience (Phase 1).
4.  */
5. import {
6.   associateRows,
7.   createRow,
8.   deleteRow,
9.   disassociateRows,
10.   getRow,
11.   listRows,
12.   updateRow,
13.   uploadFileImage,
14.   type DataverseRow,
15. } from '../lib/dataverseClient';
16. import { createRestaurant } from './restaurants';
17. import {
18.   ACTIVE_SUBMISSION_STATUSES,
19.   ENTITY_SETS,
20.   MAX_ACTIVE_SUBMISSIONS,
21.   SUBMISSION_TAG_RELATIONSHIP,
22.   SubmissionStatus,
23.   type SubmissionStatusValue,
24. } from './constants';
25. import type { TagRow } from './tags';
26. 
27. export interface PoutineSubmissionRow {
28.   rpo_poutinesubmissionid: string;
29.   rpo_name: string;
30.   rpo_description: string | null;
31.   rpo_price: number | null;
32.   rpo_status: SubmissionStatusValue;
33.   restaurantId: string | null;
34.   restaurantName: string | null;
35.   createdOn: string | null;
36.   tags: TagRow[];
37. }
38. 
39. const SUBMISSION_SELECT = ['rpo_poutinesubmissionid', 'rpo_name', 'rpo_description', 'rpo_price', 'rpo_status', 'rpo_restaurantid', 'createdon'];
40. const TAG_EXPAND = `${SUBMISSION_TAG_RELATIONSHIP}($select=rpo_tagid,rpo_name)`;
41. 
42. function escapeODataString(value: string): string {
43.   return value.replace(/'/g, "''");
44. }
45. 
46. function toSubmissionRow(row: DataverseRow): PoutineSubmissionRow {
47.   const restaurantName = row['_rpo_restaurantid_value@OData.Community.Display.V1.FormattedValue'] as
48.     | string
49.     | undefined;
50.   const relatedTags = (row[SUBMISSION_TAG_RELATIONSHIP] as DataverseRow[] | undefined) ?? [];
51.   return {
52.     rpo_poutinesubmissionid: String(row.rpo_poutinesubmissionid),
53.     rpo_name: (row.rpo_name as string | undefined) ?? '',
54.     rpo_description: (row.rpo_description as string | null | undefined) ?? null,
55.     rpo_price: (row.rpo_price as number | null | undefined) ?? null,
56.     rpo_status: (row.rpo_status as SubmissionStatusValue | undefined) ?? SubmissionStatus.Draft,
57.     restaurantId: (row._rpo_restaurantid_value as string | null | undefined) ?? null,
58.     restaurantName: restaurantName ?? null,
59.     createdOn: (row.createdon as string | null | undefined) ?? null,
60.     tags: relatedTags.map((t) => ({ rpo_tagid: String(t.rpo_tagid), rpo_name: (t.rpo_name as string) ?? '' })),
61.   };
62. }
63. 
64. /** List all submissions created by the given SystemUser, newest first, including their tags. */
65. export async function listMySubmissions(submitterId: string): Promise<PoutineSubmissionRow[]> {
66.   const rows = await listRows(ENTITY_SETS.poutineSubmissions, {
67.     select: SUBMISSION_SELECT,
68.     filter: `_rpo_submitterid_value eq '${escapeODataString(submitterId)}'`,
69.     orderBy: ['createdon desc'],
70.     expand: TAG_EXPAND,
71.   });
72.   return rows.map(toSubmissionRow);
73. }
74. 
75. /** Count how many of the submitter's submissions are in an "active" (cap-counting) status. */
76. export async function countActiveSubmissions(submitterId: string): Promise<number> {
77.   const statusFilter = ACTIVE_SUBMISSION_STATUSES.map((s) => `rpo_status eq ${s}`).join(' or ');
78.   const rows = await listRows(ENTITY_SETS.poutineSubmissions, {
79.     select: ['rpo_poutinesubmissionid'],
80.     filter: `_rpo_submitterid_value eq '${escapeODataString(submitterId)}' and (${statusFilter})`,
81.   });
82.   return rows.length;
83. }
84. 
85. export interface CreateSubmissionInput {
86.   submitterId: string;
87.   /** GUID of an existing restaurant, when the employee picked one from search results. */
88.   existingRestaurantId?: string;
89.   /** Required when existingRestaurantId is not provided. */
90.   newRestaurantName?: string;
91.   newRestaurantAddress?: string;
92.   name: string;
93.   description: string;
94.   price: number | null;
95.   status: typeof SubmissionStatus.Draft | typeof SubmissionStatus.Submitted;
96.   tagIds: string[];
97.   photo?: File;
98. }
99. 
100. /**
101.  * Creates a PoutineSubmission (creating its Restaurant first if a new one was entered),
102.  * associates the selected tags, and uploads the photo if one was provided.
103.  *
104.  * Callers must enforce the active-submission cap (via {@link countActiveSubmissions})
105.  * before calling this — it is not re-checked here to keep this function a single
106.  * atomic sequence of Dataverse calls.
107.  */
108. export async function createSubmission(input: CreateSubmissionInput): Promise<PoutineSubmissionRow> {
109.   let restaurantId = input.existingRestaurantId;
110.   if (!restaurantId) {
111.     if (!input.newRestaurantName?.trim() || !input.newRestaurantAddress?.trim()) {
112.       throw new Error('A restaurant name and address are required when no existing restaurant is selected.');
113.     }
114.     const restaurant = await createRestaurant(input.newRestaurantName, input.newRestaurantAddress);
115.     restaurantId = restaurant.rpo_restaurantid;
116.   }
117. 
118.   const created = await createRow(ENTITY_SETS.poutineSubmissions, {
119.     rpo_name: input.name.trim(),
120.     rpo_description: input.description.trim() || null,
121.     rpo_price: input.price,
122.     rpo_status: input.status,
123.     'rpo_restaurantid@odata.bind': `/${ENTITY_SETS.restaurants}(${restaurantId})`,
124.     'rpo_submitterid@odata.bind': `/${ENTITY_SETS.systemUsers}(${input.submitterId})`,
125.   });
126.   const submissionId = String(created.rpo_poutinesubmissionid);
127. 
128.   for (const tagId of input.tagIds) {
129.     await associateRows(
130.       ENTITY_SETS.poutineSubmissions,
131.       submissionId,
132.       SUBMISSION_TAG_RELATIONSHIP,
133.       ENTITY_SETS.tags,
134.       tagId,
135.     );
136.   }
137. 
138.   if (input.photo) {
139.     await uploadFileImage(ENTITY_SETS.poutineSubmissions, submissionId, 'rpo_photo', input.photo);
140.   }
141. 
142.   return getSubmission(submissionId);
143. }
144. 
145. /** Fetch a single submission (with its tags) by id. */
146. export async function getSubmission(submissionId: string): Promise<PoutineSubmissionRow> {
147.   const row = await getRow(ENTITY_SETS.poutineSubmissions, submissionId, [...SUBMISSION_SELECT]);
148.   // GetItem doesn't accept $expand in this connector op the way List does for our purposes here,
149.   // so tags are fetched separately and merged in.
150.   const tags = await getSubmissionTags(submissionId);
151.   return { ...toSubmissionRow(row), tags };
152. }
153. 
154. /** Fetch the tags currently associated with a submission. */
155. export async function getSubmissionTags(submissionId: string): Promise<TagRow[]> {
156.   const rows = await listRows(ENTITY_SETS.poutineSubmissions, {
157.     select: ['rpo_poutinesubmissionid'],
158.     filter: `rpo_poutinesubmissionid eq '${escapeODataString(submissionId)}'`,
159.     expand: TAG_EXPAND,
160.     top: 1,
161.   });
162.   const related = (rows[0]?.[SUBMISSION_TAG_RELATIONSHIP] as DataverseRow[] | undefined) ?? [];
163.   return related.map((t) => ({ rpo_tagid: String(t.rpo_tagid), rpo_name: (t.rpo_name as string) ?? '' }));
164. }
165. 
166. export interface UpdateSubmissionInput {
167.   name: string;
168.   description: string;
169.   price: number | null;
170.   status: SubmissionStatusValue;
171.   existingRestaurantId?: string;
172.   newRestaurantName?: string;
173.   newRestaurantAddress?: string;
174.   tagIds: string[];
175.   photo?: File;
176. }
177. 
178. /** Updates a Draft submission's fields, restaurant, tags (diffed), and optionally its photo. */
179. export async function updateSubmission(submissionId: string, input: UpdateSubmissionInput): Promise<PoutineSubmissionRow> {
180.   let restaurantId = input.existingRestaurantId;
181.   if (!restaurantId) {
182.     if (!input.newRestaurantName?.trim() || !input.newRestaurantAddress?.trim()) {
183.       throw new Error('A restaurant name and address are required when no existing restaurant is selected.');
184.     }
185.     const restaurant = await createRestaurant(input.newRestaurantName, input.newRestaurantAddress);
186.     restaurantId = restaurant.rpo_restaurantid;
187.   }
188. 
189.   await updateRow(ENTITY_SETS.poutineSubmissions, submissionId, {
190.     rpo_name: input.name.trim(),
191.     rpo_description: input.description.trim() || null,
192.     rpo_price: input.price,
193.     rpo_status: input.status,
194.     'rpo_restaurantid@odata.bind': `/${ENTITY_SETS.restaurants}(${restaurantId})`,
195.   });
196. 
197.   const currentTags = await getSubmissionTags(submissionId);
198.   const currentTagIds = new Set(currentTags.map((t) => t.rpo_tagid));
199.   const nextTagIds = new Set(input.tagIds);
200. 
201.   for (const tagId of nextTagIds) {
202.     if (!currentTagIds.has(tagId)) {
203.       await associateRows(ENTITY_SETS.poutineSubmissions, submissionId, SUBMISSION_TAG_RELATIONSHIP, ENTITY_SETS.tags, tagId);
204.     }
205.   }
206.   for (const tagId of currentTagIds) {
207.     if (!nextTagIds.has(tagId)) {
208.       await disassociateRows(ENTITY_SETS.poutineSubmissions, submissionId, SUBMISSION_TAG_RELATIONSHIP, ENTITY_SETS.tags, tagId);
209.     }
210.   }
211. 
212.   if (input.photo) {
213.     await uploadFileImage(ENTITY_SETS.poutineSubmissions, submissionId, 'rpo_photo', input.photo);
214.   }
215. 
216.   return getSubmission(submissionId);
217. }
218. 
219. /** Hard-deletes a submission. UI restricts this action to the employee's own Draft submissions. */
220. export async function withdrawSubmission(submissionId: string): Promise<void> {
221.   await deleteRow(ENTITY_SETS.poutineSubmissions, submissionId);
222. }
223. 
224. export { MAX_ACTIVE_SUBMISSIONS };
225.

1. /**
2.  * Thin wrapper around the auto-generated MicrosoftDataverseService.
3.  *
4.  * The Dataverse *connector* (shared_commondataserviceforapps) differs from native
5.  * Dataverse: it generates a single untyped service whose operations require an
6.  * `organization` (the Dataverse org URL) plus explicit prefer/accept headers.
7.  *
8.  * This module centralizes that boilerplate so feature modules under `src/data/`
9.  * can call simple list/get/create/update/delete/associate methods and work with
10.  * plain row objects, instead of hand-rolling fetch/axios calls against Dataverse.
11.  *
12.  * Pattern follows microsoft/PowerAppsCodeApps `samples/DataverseConnector`.
13.  */
14. import { getContext } from '@microsoft/power-apps/app';
15. import { MicrosoftDataverseService } from '../generated';
16. 
17. const PREFER = 'return=representation';
18. // Reads ask Dataverse to include annotations so lookup display names come back as
19. // `_<field>_value@OData.Community.Display.V1.FormattedValue`.
20. const READ_PREFER = 'odata.include-annotations="*"';
21. const ACCEPT = 'application/json';
22. 
23. /** A Dataverse row is a flat object of column name -> value (plus @odata.* annotations). */
24. export type DataverseRow = Record<string, unknown>;
25. 
26. export interface ListOptions {
27.   select?: string[];
28.   filter?: string;
29.   orderBy?: string[];
30.   top?: number;
31.   expand?: string;
32. }
33. 
34. let cachedOrgUrl: string | undefined;
35. 
36. /** Resolves and caches the Dataverse org URL from the Power SDK context. */
37. export async function getOrgUrl(): Promise<string> {
38.   if (cachedOrgUrl) return cachedOrgUrl;
39.   const ctx = await getContext();
40.   const orgUrl = ctx.app.dataverseOrgUrl;
41.   if (!orgUrl) {
42.     throw new Error(
43.       'Dataverse org URL is not available from the Power Platform context (context.app.dataverseOrgUrl is undefined).',
44.     );
45.   }
46.   cachedOrgUrl = orgUrl;
47.   return orgUrl;
48. }
49. 
50. /** Unwraps the connector result envelope, throwing a readable error on failure. */
51. function unwrap<T>(result: { success?: boolean; data?: T; error?: { message?: string } }): T {
52.   if (result.success === false) {
53.     let message = result.error?.message ?? 'Unknown Dataverse connector error';
54.     // The connector often returns a JSON string in error.message; surface the inner message.
55.     try {
56.       const parsed = JSON.parse(message) as { Message?: string };
57.       if (parsed.Message) message = parsed.Message;
58.     } catch {
59.       // not JSON — use as-is
60.     }
61.     throw new Error(message);
62.   }
63.   return result.data as T;
64. }
65. 
66. /** List rows from a Dataverse table via the connector. entityName is the plural entity set name. */
67. export async function listRows(entityName: string, options: ListOptions = {}): Promise<DataverseRow[]> {
68.   const org = await getOrgUrl();
69.   const result = await MicrosoftDataverseService.ListRecordsWithOrganization(
70.     org,
71.     entityName,
72.     READ_PREFER,
73.     ACCEPT,
74.     undefined, // x-ms-odata-metadata-full
75.     undefined, // MSCRM.IncludeMipSensitivityLabel
76.     options.select?.join(','),
77.     options.filter,
78.     options.orderBy?.join(','),
79.     options.expand,
80.     undefined, // fetchXml
81.     options.top,
82.   );
83.   const data = unwrap<{ value?: DataverseRow[] }>(result);
84.   return data.value ?? [];
85. }
86. 
87. /** Get a single row by its primary-key GUID. */
88. export async function getRow(entityName: string, recordId: string, select?: string[]): Promise<DataverseRow> {
89.   const org = await getOrgUrl();
90.   const result = await MicrosoftDataverseService.GetItemWithOrganization(
91.     READ_PREFER,
92.     ACCEPT,
93.     org,
94.     entityName,
95.     recordId,
96.     undefined,
97.     undefined,
98.     select?.join(','),
99.   );
100.   return unwrap<DataverseRow>(result);
101. }
102. 
103. /** Create a new row. Returns the created row (including its primary-key GUID). */
104. export async function createRow(entityName: string, item: DataverseRow): Promise<DataverseRow> {
105.   const org = await getOrgUrl();
106.   const result = await MicrosoftDataverseService.CreateRecordWithOrganization(PREFER, ACCEPT, org, entityName, item);
107.   // The connector's generated typing declares CreateRecord's response as `void`, but Dataverse
108.   // honors the `return=representation` Prefer header and returns the full created row — cast
109.   // through unknown to recover it (verified against the connector's OpenAPI schema).
110.   return unwrap<unknown>(result as unknown as { success?: boolean; data?: unknown }) as DataverseRow;
111. }
112. 
113. /** Update an existing row (upsert semantics). */
114. export async function updateRow(entityName: string, recordId: string, item: DataverseRow): Promise<DataverseRow> {
115.   const org = await getOrgUrl();
116.   const result = await MicrosoftDataverseService.UpdateRecordWithOrganization(
117.     PREFER,
118.     ACCEPT,
119.     org,
120.     entityName,
121.     recordId,
122.     item,
123.   );
124.   return unwrap<DataverseRow>(result);
125. }
126. 
127. /** Delete a row by its primary-key GUID. */
128. export async function deleteRow(entityName: string, recordId: string): Promise<void> {
129.   const org = await getOrgUrl();
130.   const result = await MicrosoftDataverseService.DeleteRecordWithOrganization(org, entityName, recordId);
131.   unwrap<void>(result);
132. }
133. 
134. /**
135.  * Associate a row with another row via a named N:N (or 1:N) relationship.
136.  * @param entityName plural entity set name of the row that owns the relationship
137.  * @param recordId GUID of that row
138.  * @param relationshipName schema name of the relationship (e.g. "rpo_PoutineSubmission_Tag")
139.  * @param targetEntityName plural entity set name of the row being linked
140.  * @param targetRecordId GUID of the row being linked
141.  */
142. export async function associateRows(
143.   entityName: string,
144.   recordId: string,
145.   relationshipName: string,
146.   targetEntityName: string,
147.   targetRecordId: string,
148. ): Promise<void> {
149.   const org = await getOrgUrl();
150.   const result = await MicrosoftDataverseService.AssociateEntitiesWithOrganization(org, entityName, recordId, relationshipName, {
151.     '@odata.id': `${org.replace(/\/$/, '')}/api/data/v9.2/${targetEntityName}(${targetRecordId})`,
152.   });
153.   unwrap<void>(result);
154. }
155. 
156. /** Removes an association created by {@link associateRows}. */
157. export async function disassociateRows(
158.   entityName: string,
159.   recordId: string,
160.   relationshipName: string,
161.   targetEntityName: string,
162.   targetRecordId: string,
163. ): Promise<void> {
164.   const org = await getOrgUrl();
165.   const result = await MicrosoftDataverseService.DisassociateEntitiesWithOrganization(
166.     org,
167.     entityName,
168.     recordId,
169.     relationshipName,
170.     `${org.replace(/\/$/, '')}/api/data/v9.2/${targetEntityName}(${targetRecordId})`,
171.   );
172.   unwrap<void>(result);
173. }
174. 
175. /** Strips the "data:<mime>;base64," prefix from a data URL, returning raw base64. */
176. function stripDataUrlPrefix(dataUrl: string): string {
177.   const comma = dataUrl.indexOf(',');
178.   return comma >= 0 ? dataUrl.slice(comma + 1) : dataUrl;
179. }
180. 
181. /** Reads a File/Blob as a base64 string (no data-URL prefix). */
182. export function fileToBase64(file: File): Promise<string> {
183.   return new Promise((resolve, reject) => {
184.     const reader = new FileReader();
185.     reader.onload = () => resolve(stripDataUrlPrefix(String(reader.result)));
186.     reader.onerror = () => reject(reader.error ?? new Error('Failed to read file'));
187.     reader.readAsDataURL(file);
188.   });
189. }
190. 
191. /** Upload a file or image to a Dataverse file/image column (e.g. "rpo_photo"). */
192. export async function uploadFileImage(
193.   entityName: string,
194.   recordId: string,
195.   columnName: string,
196.   file: File,
197. ): Promise<void> {
198.   const org = await getOrgUrl();
199.   const base64 = await fileToBase64(file);
200.   // Per the connector's OpenAPI schema, the body is binary (base64-encoded here) and
201.   // content-type defaults to "application/octet-stream" — the connector accepts that for
202.   // both File and Image column types.
203.   const result = await MicrosoftDataverseService.UpdateEntityFileImageFieldContentWithOrganization(
204.     'application/octet-stream',
205.     org,
206.     entityName,
207.     recordId,
208.     columnName,
209.     base64,
210.     file.name,
211.   );
212.   unwrap<void>(result);
213. }
214.

1. /**
2.  * Restaurant lookup + find-or-create helpers used by the submission form so employees
3.  * can attach a new poutine to an existing Restaurant row instead of creating duplicates.
4.  */
5. import { createRow, getRow, listRows, type DataverseRow } from '../lib/dataverseClient';
6. import { ENTITY_SETS } from './constants';
7. 
8. export interface RestaurantRow {
9.   rpo_restaurantid: string;
10.   rpo_name: string;
11.   rpo_address?: string | null;
12. }
13. 
14. function toRestaurantRow(row: DataverseRow): RestaurantRow {
15.   return {
16.     rpo_restaurantid: String(row.rpo_restaurantid),
17.     rpo_name: (row.rpo_name as string | undefined) ?? '',
18.     rpo_address: (row.rpo_address as string | null | undefined) ?? null,
19.   };
20. }
21. 
22. function escapeODataString(value: string): string {
23.   return value.replace(/'/g, "''");
24. }
25. 
26. /** Search existing restaurants by (partial, case-insensitive) name match. */
27. export async function searchRestaurants(query: string, top = 8): Promise<RestaurantRow[]> {
28.   const trimmed = query.trim();
29.   if (!trimmed) return [];
30.   const rows = await listRows(ENTITY_SETS.restaurants, {
31.     select: ['rpo_restaurantid', 'rpo_name', 'rpo_address'],
32.     filter: `contains(rpo_name, '${escapeODataString(trimmed)}')`,
33.     orderBy: ['rpo_name asc'],
34.     top,
35.   });
36.   return rows.map(toRestaurantRow);
37. }
38. 
39. /** Creates a new Restaurant row. Latitude/longitude are left unset (populated later by a separate geocoding flow). */
40. export async function createRestaurant(name: string, address: string): Promise<RestaurantRow> {
41.   const created = await createRow(ENTITY_SETS.restaurants, {
42.     rpo_name: name.trim(),
43.     rpo_address: address.trim(),
44.   });
45.   return toRestaurantRow(created);
46. }
47. 
48. /** Fetch a single restaurant by id (used to pre-fill the picker when editing an existing submission). */
49. export async function getRestaurantById(restaurantId: string): Promise<RestaurantRow> {
50.   const row = await getRow(ENTITY_SETS.restaurants, restaurantId, ['rpo_restaurantid', 'rpo_name', 'rpo_address']);
51.   return toRestaurantRow(row);
52. }
53.

1. /** Tag lookup helpers — Tags are seeded master data (no create-from-app in this phase). */
2. import { listRows, type DataverseRow } from '../lib/dataverseClient';
3. import { ENTITY_SETS } from './constants';
4. 
5. export interface TagRow {
6.   rpo_tagid: string;
7.   rpo_name: string;
8. }
9. 
10. function toTagRow(row: DataverseRow): TagRow {
11.   return {
12.     rpo_tagid: String(row.rpo_tagid),
13.     rpo_name: (row.rpo_name as string | undefined) ?? '',
14.   };
15. }
16. 
17. /** List all seeded tags, sorted by name. */
18. export async function listTags(): Promise<TagRow[]> {
19.   const rows = await listRows(ENTITY_SETS.tags, {
20.     select: ['rpo_tagid', 'rpo_name'],
21.     orderBy: ['rpo_name asc'],
22.   });
23.   return rows.map(toTagRow);
24. }
25.

1. /**
2.  * Resolves the current employee's `systemuserid` from the Power Platform SDK context.
3.  *
4.  * The code app runs as the signed-in user, so we match their Azure AD object id (or
5.  * fall back to their UPN/email) against the `systemusers` table to find the SystemUser
6.  * row that PoutineSubmission.rpo_submitterid should point at.
7.  */
8. import { getContext } from '@microsoft/power-apps/app';
9. import { listRows } from '../lib/dataverseClient';
10. import { ENTITY_SETS } from './constants';
11. 
12. export interface CurrentUser {
13.   systemUserId: string;
14.   fullName: string;
15.   userPrincipalName: string;
16. }
17. 
18. let cachedUser: CurrentUser | undefined;
19. 
20. function escapeODataString(value: string): string {
21.   return value.replace(/'/g, "''");
22. }
23. 
24. /** Resolves and caches the current employee's SystemUser row. */
25. export async function getCurrentUser(): Promise<CurrentUser> {
26.   if (cachedUser) return cachedUser;
27. 
28.   const ctx = await getContext();
29.   const { objectId, userPrincipalName, fullName } = ctx.user;
30. 
31.   let rows = objectId
32.     ? await listRows(ENTITY_SETS.systemUsers, {
33.         select: ['systemuserid', 'fullname', 'internalemailaddress'],
34.         filter: `azureactivedirectoryobjectid eq '${escapeODataString(objectId)}'`,
35.         top: 1,
36.       })
37.     : [];
38. 
39.   if (rows.length === 0 && userPrincipalName) {
40.     rows = await listRows(ENTITY_SETS.systemUsers, {
41.       select: ['systemuserid', 'fullname', 'internalemailaddress'],
42.       filter: `internalemailaddress eq '${escapeODataString(userPrincipalName)}'`,
43.       top: 1,
44.     });
45.   }
46. 
47.   const row = rows[0];
48.   if (!row) {
49.     throw new Error(
