4. interface TagMultiSelectProps {
5.   tags: TagRow[];
6.   selectedTagIds: string[];
7.   onChange: (tagIds: string[]) => void;
8.   disabled?: boolean;
9. }
10. 
11. /** Chip-style multi-select for the seeded Tag table (DESIGN.md `chip-tag` component). */
12. export function TagMultiSelect({ tags, selectedTagIds, onChange, disabled }: TagMultiSelectProps) {
13.   function toggle(tagId: string) {
14.     if (selectedTagIds.includes(tagId)) {
15.       onChange(selectedTagIds.filter((id) => id !== tagId));
16.     } else {
17.       onChange([...selectedTagIds, tagId]);
18.     }
19.   }
20. 
21.   if (tags.length === 0) {
22.     return <p className="form-field__hint">No tags are available yet.</p>;
23.   }
24. 
25.   return (
26.     <div className="tag-multi-select" role="group" aria-label="Tags">
27.       {tags.map((tag) => {
28.         const isSelected = selectedTagIds.includes(tag.rpo_tagid);
29.         return (
30.           <button
31.             type="button"
32.             key={tag.rpo_tagid}
33.             className={`tag-chip${isSelected ? ' tag-chip--selected' : ''}`}
34.             aria-pressed={isSelected}
35.             disabled={disabled}
36.             onClick={() => toggle(tag.rpo_tagid)}
37.           >
38.             {tag.rpo_name}
39.           </button>
40.         );
41.       })}
42.     </div>
43.   );
44. }
