1. import { useState } from 'react';
2. import { EmptyState } from '../EmptyState/EmptyState';
3. import { StatusBadge } from '../StatusBadge/StatusBadge';
4. import { SubmissionStatus, type SubmissionStatusValue } from '../../data/constants';
5. import type { PoutineSubmissionRow } from '../../data/submissions';
6. import './MySubmissionsList.css';
7. 
8. interface MySubmissionsListProps {
9.   submissions: PoutineSubmissionRow[];
10.   onEdit: (submission: PoutineSubmissionRow) => void;
11.   onWithdraw: (submission: PoutineSubmissionRow) => Promise<void>;
12. }
13. 
14. const EDITABLE_STATUSES: SubmissionStatusValue[] = [SubmissionStatus.Draft];
15. 
16. function formatPrice(price: number | null): string {
17.   return price === null ? '\u2014' : `$${price.toFixed(2)}`;
18. }
19. 
20. /** Card list of the current employee's own submissions, with Edit/Withdraw restricted to Drafts. */
21. export function MySubmissionsList({ submissions, onEdit, onWithdraw }: MySubmissionsListProps) {
22.   const [withdrawingId, setWithdrawingId] = useState<string | null>(null);
23. 
24.   if (submissions.length === 0) {
25.     return (
26.       <EmptyState
27.         title="No submissions yet"
28.         description="Once you submit a poutine, it will show up here so you can track its status, edit a draft, or withdraw it."
29.       />
30.     );
31.   }
32. 
33.   async function handleWithdraw(submission: PoutineSubmissionRow) {
34.     if (!window.confirm(`Withdraw "${submission.rpo_name}"? This can't be undone.`)) return;
35.     setWithdrawingId(submission.rpo_poutinesubmissionid);
36.     try {
37.       await onWithdraw(submission);
38.     } finally {
39.       setWithdrawingId(null);
40.     }
41.   }
42. 
43.   return (
44.     <ul className="my-submissions-list">
45.       {submissions.map((submission) => {
46.         const isEditable = EDITABLE_STATUSES.includes(submission.rpo_status);
47.         return (
48.           <li className="submission-card" key={submission.rpo_poutinesubmissionid}>
49.             <div className="submission-card__header">
50.               <h3 className="submission-card__title">{submission.rpo_name}</h3>
51.               <StatusBadge status={submission.rpo_status} />
52.             </div>
53.             {submission.restaurantName && <p className="submission-card__restaurant">{submission.restaurantName}</p>}
54.             <p className="submission-card__meta">{formatPrice(submission.rpo_price)}</p>
55.             {submission.tags.length > 0 && (
56.               <div className="submission-card__tags">
57.                 {submission.tags.map((tag) => (
58.                   <span key={tag.rpo_tagid} className="tag-chip">
59.                     {tag.rpo_name}
60.                   </span>
61.                 ))}
62.               </div>
63.             )}
64.             {isEditable && (
65.               <div className="submission-card__actions">
66.                 <button type="button" className="btn btn--secondary btn--small" onClick={() => onEdit(submission)}>
67.                   Edit
68.                 </button>
69.                 <button
70.                   type="button"
71.                   className="btn btn--destructive btn--small"
72.                   disabled={withdrawingId === submission.rpo_poutinesubmissionid}
73.                   onClick={() => handleWithdraw(submission)}
74.                 >
75.                   {withdrawingId === submission.rpo_poutinesubmissionid ? 'Withdrawing…' : 'Withdraw'}
76.                 </button>
77.               </div>
78.             )}
79.           </li>
80.         );
81.       })}
82.     </ul>
83.   );
84. }
