input.file_text:
/**
 * Try lookup helpers (Phase 2, read-only). A Try is an employee's honor-system
 * self-declaration that they tried a poutine — see ARCHITECTURE.md's data model.
 * Try *creation* is out of scope for this phase (Phase 3); this module only
 * reads existing Try rows so the Browse/detail views can surface try counts.
 */
import { listRows, type DataverseRow } from '../lib/dataverseClient';
import { ENTITY_SETS } from './constants';

export interface TryRow {
  rpo_tryid: string;
  poutineSubmissionId: string | null;
  employeeId: string | null;
  employeeName: string | null;
  triedOn: string | null;
}

const TRY_SELECT = ['rpo_tryid', 'rpo_poutinesubmissionid', 'rpo_employeeid', 'rpo_triedon'];

function escapeODataString(value: string): string {
  return value.replace(/'/g, "''");
}

function toTryRow(row: DataverseRow): TryRow {
  return {
    rpo_tryid: String(row.rpo_tryid),
    poutineSubmissionId: (row._rpo_poutinesubmissionid_value as string | null | undefined) ?? null,
    employeeId: (row._rpo_employeeid_value as string | null | undefined) ?? null,
    employeeName:
      (row['_rpo_employeeid_value@OData.Community.Display.V1.FormattedValue'] as string | undefined) ?? null,
    triedOn: (row.rpo_triedon as string | null | undefined) ?? null,
  };
}

/**
 * List all Try rows pointing at any of the given PoutineSubmission ids.
 * Used to compute try counts for the Browse feed and to resolve the Try ids
 * needed to fetch the Reviews tied to a submission (Review only links to Try,
 * not directly to PoutineSubmission — see rpo_Review's schema).
 */
export async function listTriesForSubmissions(submissionIds: string[]): Promise<TryRow[]> {
  if (submissionIds.length === 0) return [];
  const filter = submissionIds
    .map((id) => `_rpo_poutinesubmissionid_value eq '${escapeODataString(id)}'`)
    .join(' or ');
  const rows = await listRows(ENTITY_SETS.tries, {
    select: TRY_SELECT,
    filter,
    orderBy: ['rpo_triedon desc'],
  });
  return rows.map(toTryRow);
}

/**
 * Review lookup helpers (Phase 2, read-only). A Review is a star rating +
 * comment left after a Try — see ARCHITECTURE.md's data model. Review
 * *creation* is out of scope for this phase (Phase 3); this module only reads
 * existing Review rows so the Browse/detail views can surface ratings.
 */
import { listRows, type DataverseRow } from '../lib/dataverseClient';
import { ENTITY_SETS } from './constants';

export interface ReviewRow {
  rpo_reviewid: string;
  tryId: string | null;
  reviewerId: string | null;
  reviewerName: string | null;
  starRating: number;
  comment: string | null;
  helpfulnessScore: number | null;
  createdOn: string | null;
}

const REVIEW_SELECT = [
  'rpo_reviewid',
  'rpo_tryid',
  'rpo_reviewerid',
  'rpo_starrating',
  'rpo_comment',
  'rpo_helpfulnessscore',
  'createdon',
];

function escapeODataString(value: string): string {
  return value.replace(/'/g, "''");
}

function toReviewRow(row: DataverseRow): ReviewRow {
  return {
    rpo_reviewid: String(row.rpo_reviewid),
    tryId: (row._rpo_tryid_value as string | null | undefined) ?? null,
    reviewerId: (row._rpo_reviewerid_value as string | null | undefined) ?? null,
    reviewerName:
      (row['_rpo_reviewerid_value@OData.Community.Display.V1.FormattedValue'] as string | undefined) ?? null,
    starRating: (row.rpo_starrating as number | undefined) ?? 0,
    comment: (row.rpo_comment as string | null | undefined) ?? null,
    helpfulnessScore: (row.rpo_helpfulnessscore as number | null | undefined) ?? null,
    createdOn: (row.createdon as string | null | undefined) ?? null,
  };
}

/**
 * List all Review rows pointing at any of the given Try ids. Reviews link to
 * PoutineSubmission indirectly via Try, so callers first resolve the Try ids
 * for a submission (see {@link listTriesForSubmissions} in `./tries`) and pass
 * them here.
 */
export async function listReviewsForTries(tryIds: string[]): Promise<ReviewRow[]> {
  if (tryIds.length === 0) return [];
  const filter = tryIds.map((id) => `_rpo_tryid_value eq '${escapeODataString(id)}'`).join(' or ');
  const rows = await listRows(ENTITY_SETS.reviews, {
    select: REVIEW_SELECT,
    filter,
    orderBy: ['createdon desc'],
  });
  return rows.map(toReviewRow);
}

/**
 * Aggregates Try/Review data per PoutineSubmission for the Browse feed and
 * detail view (Phase 2). Read-only: Try/Review *creation* is Phase 3.
 */
import { listTriesForSubmissions, type TryRow } from './tries';
import { listReviewsForTries, type ReviewRow } from './reviews';

export interface SubmissionAggregate {
  tryCount: number;
  reviewCount: number;
  /** Simple (unweighted) average of star ratings, or null when there are no reviews yet. */
  averageRating: number | null;
}

function emptyAggregate(): SubmissionAggregate {
  return { tryCount: 0, reviewCount: 0, averageRating: null };
}

/**
 * Computes try count / review count / average rating for each of the given
 * submission ids in just two Dataverse round-trips (all Tries for the set,
 * then all Reviews for those Tries), regardless of how many submissions are
 * passed in — appropriate at this app's demo scale.
 */
export async function getAggregatesForSubmissions(
  submissionIds: string[],
): Promise<Map<string, SubmissionAggregate>> {
  const aggregates = new Map<string, SubmissionAggregate>();
  for (const id of submissionIds) aggregates.set(id, emptyAggregate());
  if (submissionIds.length === 0) return aggregates;

  const tries = await listTriesForSubmissions(submissionIds);
  const tryIdToSubmissionId = new Map<string, string>();
  for (const t of tries) {
    if (!t.poutineSubmissionId) continue;
    const agg = aggregates.get(t.poutineSubmissionId);
    if (agg) agg.tryCount += 1;
    tryIdToSubmissionId.set(t.rpo_tryid, t.poutineSubmissionId);
  }

  const tryIds = tries.map((t) => t.rpo_tryid);
  const reviews = await listReviewsForTries(tryIds);
  const ratingSums = new Map<string, { sum: number; count: number }>();
  for (const r of reviews) {
    const submissionId = r.tryId ? tryIdToSubmissionId.get(r.tryId) : undefined;
    if (!submissionId) continue;
    const agg = aggregates.get(submissionId);
    if (agg) agg.reviewCount += 1;
    const bucket = ratingSums.get(submissionId) ?? { sum: 0, count: 0 };
    bucket.sum += r.starRating;
    bucket.count += 1;
    ratingSums.set(submissionId, bucket);
  }
  for (const [submissionId, bucket] of ratingSums) {
    const agg = aggregates.get(submissionId);
    if (agg && bucket.count > 0) agg.averageRating = bucket.sum / bucket.count;
  }

  return aggregates;
}

export interface SubmissionFeedback {
  tries: TryRow[];
  reviews: ReviewRow[];
}

/** Fetches every Try and Review tied to a single submission, for the detail view. */
export async function getFeedbackForSubmission(submissionId: string): Promise<SubmissionFeedback> {
  const tries = await listTriesForSubmissions([submissionId]);
  const tryIds = tries.map((t) => t.rpo_tryid);
  const reviews = await listReviewsForTries(tryIds);
  return { tries, reviews };
}

