42.     starRating: (row.rpo_starrating as number | undefined) ?? 0,
43.     comment: (row.rpo_comment as string | null | undefined) ?? null,
44.     helpfulnessScore: (row.rpo_helpfulnessscore as number | null | undefined) ?? null,
