8.   aggregate?: SubmissionAggregate;
9.   onSelect: (submission: PoutineSubmissionRow) => void;
10. }
11. 
12. function formatPrice(price: number | null): string {
13.   return price === null ? '\u2014' : `$${price.toFixed(2)}`;
14. }
15. 
16. /** Renders the "tries/reviews" line: average rating when reviews exist, else a try count, else a nudge. */
17. function formatAggregate(aggregate: SubmissionAggregate | undefined): string {
18.   if (!aggregate || aggregate.tryCount === 0) return 'Not tried yet';
19.   if (aggregate.reviewCount === 0) {
20.     return `${aggregate.tryCount} ${aggregate.tryCount === 1 ? 'try' : 'tries'} \u00b7 no reviews yet`;
21.   }
22.   const rating = aggregate.averageRating ?? 0;
23.   return `\u2605 ${rating.toFixed(1)} (${aggregate.reviewCount} ${aggregate.reviewCount === 1 ? 'review' : 'reviews'}) \u00b7 ${aggregate.tryCount} ${aggregate.tryCount === 1 ? 'try' : 'tries'}`;
24. }
25. 
26. /** A single poutine in the public Browse feed. Card treatment matches the Phase 1 submission-card. */
27. export function PoutineCard({ submission, aggregate, onSelect }: PoutineCardProps) {
28.   return (
29.     <li className="poutine-card">
30.       <button type="button" className="poutine-card__button" onClick={() => onSelect(submission)}>
