36.               🍟
37.             </div>
38.           )}
39.         </div>
40.         <div className="poutine-card__body">
41.           <h3 className="poutine-card__title">{submission.rpo_name}</h3>
42.           {submission.restaurantName && <p className="poutine-card__restaurant">{submission.restaurantName}</p>}
