1. import { useEffect, useState } from 'react';
2. import { EmptyState } from '../EmptyState/EmptyState';
3. import type { RestaurantRow } from '../../data/restaurants';
4. import { getRestaurantById } from '../../data/restaurants';
5. import type { PoutineSubmissionRow } from '../../data/submissions';
6. import { getSubmissionWithPhoto } from '../../data/submissions';
7. import { getFeedbackForSubmission, type SubmissionFeedback } from '../../data/feedback';
8. import '../TagMultiSelect/TagMultiSelect.css';
9. import './SubmissionDetail.css';
10. 
11. interface SubmissionDetailProps {
12.   submissionId: string;
13.   onBack: () => void;
14. }
15. 
16. function formatPrice(price: number | null): string {
17.   return price === null ? '\u2014' : `$${price.toFixed(2)}`;
18. }
19. 
20. function formatDate(value: string | null): string {
21.   if (!value) return '';
22.   return new Date(value).toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
23. }
