25. /**
26.  * Read-only detail view for one approved poutine: full submission info, restaurant
27.  * details, tags, and any existing Tries/Reviews. Try/Review *creation* is Phase 3 —
28.  * this phase only displays what already exists.
29.  */
30. export function SubmissionDetail({ submissionId, onBack }: SubmissionDetailProps) {
31.   const [submission, setSubmission] = useState<PoutineSubmissionRow | null>(null);
32.   const [restaurant, setRestaurant] = useState<RestaurantRow | null>(null);
33.   const [feedback, setFeedback] = useState<SubmissionFeedback | null>(null);
34.   const [isLoading, setIsLoading] = useState(true);
35.   const [loadError, setLoadError] = useState<string | null>(null);
36. 
37.   useEffect(() => {
38.     let cancelled = false;
39.     async function load() {
40.       try {
41.         setIsLoading(true);
42.         setLoadError(null);
43.         const sub = await getSubmissionWithPhoto(submissionId);
44.         if (cancelled) return;
45.         setSubmission(sub);
46.         const [restaurantRow, feedbackData] = await Promise.all([
47.           sub.restaurantId ? getRestaurantById(sub.restaurantId) : Promise.resolve(null),
48.           getFeedbackForSubmission(submissionId),
49.         ]);
50.         if (cancelled) return;
51.         setRestaurant(restaurantRow);
52.         setFeedback(feedbackData);
53.       } catch (err) {
54.         if (!cancelled) setLoadError(err instanceof Error ? err.message : 'Failed to load this poutine.');
55.       } finally {
56.         if (!cancelled) setIsLoading(false);
57.       }
58.     }
59.     load();
60.     return () => {
61.       cancelled = true;
62.     };
63.   }, [submissionId]);
64. 
65.   if (isLoading) {
66.     return <EmptyState title="Loading" description="Loading this poutine…" />;
67.   }
68. 
69.   if (loadError || !submission) {
70.     return <EmptyState title="Couldn't load this poutine" description={loadError ?? 'Unknown error.'} />;
71.   }
72. 
73.   return (
74.     <div className="submission-detail">
75.       <button type="button" className="btn btn--secondary btn--small submission-detail__back" onClick={onBack}>
76.         {'\u2190'} Back to Browse
77.       </button>
78. 
79.       <div className="submission-detail__card">
80.         {submission.photoDataUrl && (
81.           <img className="submission-detail__photo" src={submission.photoDataUrl} alt={submission.rpo_name} />
82.         )}
83. 
84.         <h1 className="submission-detail__title">{submission.rpo_name}</h1>
85.         {restaurant && <p className="submission-detail__restaurant">{restaurant.rpo_name}</p>}
86.         {restaurant?.rpo_address && <p className="submission-detail__address">{restaurant.rpo_address}</p>}
87.         <p className="submission-detail__meta">{formatPrice(submission.rpo_price)}</p>
88. 
89.         {submission.tags.length > 0 && (
90.           <div className="submission-detail__tags">
91.             {submission.tags.map((tag) => (
92.               <span key={tag.rpo_tagid} className="tag-chip">
93.                 {tag.rpo_name}
94.               </span>
95.             ))}
96.           </div>
97.         )}
98. 
99.         {submission.rpo_description && <p className="submission-detail__description">{submission.rpo_description}</p>}
100.       </div>
101. 
102.       <section className="submission-detail__feedback">
103.         <h2 className="submission-detail__section-title">
104.           Tries {feedback ? `(${feedback.tries.length})` : ''}
105.         </h2>
106.         {!feedback || feedback.tries.length === 0 ? (
107.           <p className="submission-detail__empty">No one has tried this poutine yet.</p>
108.         ) : (
109.           <ul className="submission-detail__try-list">
110.             {feedback.tries.map((t) => (
111.               <li key={t.rpo_tryid} className="submission-detail__try-item">
112.                 {t.employeeName ?? 'An employee'} tried this{t.triedOn ? ` on ${formatDate(t.triedOn)}` : ''}
113.               </li>
114.             ))}
115.           </ul>
116.         )}
117. 
118.         <h2 className="submission-detail__section-title">
119.           Reviews {feedback ? `(${feedback.reviews.length})` : ''}
120.         </h2>
121.         {!feedback || feedback.reviews.length === 0 ? (
122.           <p className="submission-detail__empty">No reviews yet.</p>
123.         ) : (
124.           <ul className="submission-detail__review-list">
125.             {feedback.reviews.map((r) => (
126.               <li key={r.rpo_reviewid} className="submission-detail__review-item">
127.                 <div className="submission-detail__review-header">
128.                   <span className="submission-detail__review-rating">{'\u2605'.repeat(r.starRating)}</span>
129.                   <span className="submission-detail__review-author">{r.reviewerName ?? 'An employee'}</span>
130.                   {r.createdOn && <span className="submission-detail__review-date">{formatDate(r.createdOn)}</span>}
131.                 </div>
132.                 {r.comment && <p className="submission-detail__review-comment">{r.comment}</p>}
133.               </li>
134.             ))}
135.           </ul>
136.         )}
137.       </section>
138.     </div>
139.   );
140. }
